// Domain 层（:domain 模块）
interface UserRepository {
    suspend fun getUser(id: String): Result<User>
    suspend fun getUsers(): Flow<List<User>>
}

class GetUserUseCase(
    private val repository: UserRepository  // 依赖接口，不依赖实现
) {
    operator fun invoke(userId: String): Flow<Resource<User>> = flow {
        emit(Resource.Loading)
        emit(repository.getUser(userId).toResource())
    }
}

// Data 层（:data 模块）
@Module
@InstallIn(SingletonComponent::class)
abstract class RepositoryModule {
    @Binds
    @Singleton
    abstract fun bindUserRepository(
        impl: UserRepositoryImpl  // 绑定实现到接口
    ): UserRepository
}

class UserRepositoryImpl @Inject constructor(
    private val api: UserApi,
    private val dao: UserDao
) : UserRepository {
    override suspend fun getUser(id: String): Result<User> {
        return try {
            val remote = api.getUser(id)
            dao.insertUser(remote.toEntity())
            Result.success(remote.toDomain())
        } catch (e: Exception) {
            val cached = dao.getUser(id)
            cached?.let { Result.success(it.toDomain()) }
                ?: Result.failure(e)
        }
    }
}

