// 方案：UiState + Channel 处理一次性事件
data class HomeUiState(
    val isLoading: Boolean = false,
    val articles: List<Article> = emptyList(),
    val error: String? = null,
    val searchQuery: String = ""
)

sealed interface HomeEvent {
    data class ShowSnackbar(val message: String) : HomeEvent
    data class NavigateToDetail(val articleId: String) : HomeEvent
}

@HiltViewModel
class HomeViewModel @Inject constructor(
    private val getArticles: GetArticlesUseCase
) : ViewModel() {

    private val _uiState = MutableStateFlow(HomeUiState())
    val uiState: StateFlow<HomeUiState> = _uiState.asStateFlow()

    // Channel 保证一次性事件不丢失、不重复消费
    private val _events = Channel<HomeEvent>(Channel.BUFFERED)
    val events: Flow<HomeEvent> = _events.receiveAsFlow()

    private val searchQuery = MutableStateFlow("")

    init {
        // 搜索防抖
        viewModelScope.launch {
            searchQuery
                .debounce(300L)
                .distinctUntilChanged()
                .flatMapLatest { query ->
                    getArticles(query)
                        .onStart { _uiState.update { it.copy(isLoading = true) } }
                        .catch { e ->
                            _uiState.update { it.copy(error = e.message) }
                            emit(emptyList())
                        }
                }
                .collect { articles ->
                    _uiState.update {
                        it.copy(isLoading = false, articles = articles, error = null)
                    }
                }
        }
    }

    fun onSearchQueryChanged(query: String) {
        _uiState.update { it.copy(searchQuery = query) }
        searchQuery.value = query
    }

    fun onArticleClicked(id: String) {
        viewModelScope.launch {
            _events.send(HomeEvent.NavigateToDetail(id))
        }
    }
}
